package msm_test;

import java.util.List;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.sounds.SoundEvent;

/**
 * The sound events of the resource pack, registered before everything else: status effects, items, events and
 * entities name them.
 */
public final class ModSounds {
    /** The event keys of the assets/<namespace>/sounds.json files, sorted. */
    public static final List<String> KEYS = List.of(
            "msm_test:chime",
            "msm_test:golem.ambient",
            "msm_test:golem.death",
            "msm_test:golem.hurt",
            "msm_test:golem.step");

    private ModSounds() {}

    /** Registers one variable-range sound event per key; a key already registered (by vanilla or another mod) is skipped. */
    public static void register() {
        for (String key : KEYS) {
            Identifier id = Identifier.parse(key);
            if (!BuiltInRegistries.SOUND_EVENT.containsKey(id)) {
                Registry.register(BuiltInRegistries.SOUND_EVENT, id, SoundEvent.createVariableRangeEvent(id));
            }
        }
    }
}
